enum SmeltFutureState<T> {
    Pending(::std::pin::Pin<Box<dyn ::std::future::Future<Output = Result<T, Box<dyn std::error::Error>>>>>),
    Resolved(T),
    Rejected(SmeltUnknown),
    Taken,
}
